        [TbAttribute1] VARCHAR(255) NULL,
        [TbAttribute2] VARCHAR(255) NULL,
        [TbAttribute3] VARCHAR(255) NULL,
        [TbAttribute4] VARCHAR(255) NULL,
        [TbAttribute5] VARCHAR(255) NULL,
        [TbAttribute6] VARCHAR(255) NULL,
        [TbAttribute7] VARCHAR(255) NULL,
        [TbAttribute8] VARCHAR(255) NULL,
        [TbAttribute9] VARCHAR(255) NULL,
        [TbAttribute10] VARCHAR(255) NULL,
        [CclCreditLineId] INT NULL,
        [StrikeType] VARCHAR(50) NULL,
        [SettleType] VARCHAR(50) NULL,
        [PutCallFlag] VARCHAR(50) NULL,
        [PremiumPaid] VARCHAR(50) NULL,
        [OpmOptionModel] VARCHAR(50) NULL,
        [ExpirationDate] DATETIME2(7) NULL,
        [Volatility] DECIMAL(28,12) NOT NULL,
        [Correlation] DECIMAL(28,12) NOT NULL,
        [OptionValue] DECIMAL(28,12) NOT NULL,
        [StrikePrice] DECIMAL(28,12) NOT NULL,
        [DeltaVolume] DECIMAL(28,12) NOT NULL,
        [Delta] DECIMAL(28,12) NOT NULL,
        [Gamma] DECIMAL(28,12) NOT NULL,
        [Vega] DECIMAL(28,12) NOT NULL,
        [Theta] DECIMAL(28,12) NOT NULL,
        [Rho] DECIMAL(28,12) NOT NULL,
        [Eta] DECIMAL(28,12) NOT NULL,
        [GasEquivalent] DECIMAL(28,12) NULL,
        [ImpliedHeatRate] DECIMAL(28,12) NULL,
        [MwhPosition] DECIMAL(28,12) NULL,
        [FileLogId]     BIGINT NULL,
        [ModifiedAtUtc] DATETIME2(3) NOT NULL CONSTRAINT [DF_PositionDetails_ModifiedAtUtc] DEFAULT (SYSUTCDATETIME()),
        CONSTRAINT [PK_PositionDetails] PRIMARY KEY NONCLUSTERED ([PositionDetailsId])
    );
END
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'CIX_PositionDetails' AND object_id = OBJECT_ID(N'[dbo].[PositionDetails]'))
    CREATE CLUSTERED INDEX [CIX_PositionDetails] ON [dbo].[PositionDetails] ([TradeMonth], [SystemDate]);
GO

-- ------------------------------------------------------------------------------------
-- Volatilities  (15 vendor columns)
-- ------------------------------------------------------------------------------------
IF OBJECT_ID(N'[dbo].[Volatilities]', N'U') IS NULL
BEGIN
    CREATE TABLE [dbo].[Volatilities]
    (
        [CreatedAt] DATETIMEOFFSET(7) NOT NULL,
        [ModifiedAt] DATETIMEOFFSET(7) NOT NULL,
        [CreatedByUser] VARCHAR(50) NULL,
        [ModifiedByUser] VARCHAR(50) NULL,
        [SystemDate] DATETIME2(7) NOT NULL,
        [ProductSpec] VARCHAR(100) NOT NULL,
        [InstrumentType] VARCHAR(100) NOT NULL,
        [StartTradeMonth] VARCHAR(50) NOT NULL,
        [EndTradeMonth] VARCHAR(50) NOT NULL,
        [PutCallFlag] VARCHAR(50) NOT NULL,
        [StrikeType] VARCHAR(50) NOT NULL,
        [StrikePrice] DECIMAL(28,12) NOT NULL,
        [Volatility] DECIMAL(28,12) NOT NULL,
        [AtmFlag] BIT NOT NULL,
        [UpdatedFlag] BIT NOT NULL,
        [FileLogId]     BIGINT NULL,
        [ModifiedAtUtc] DATETIME2(3) NOT NULL CONSTRAINT [DF_Volatilities_ModifiedAtUtc] DEFAULT (SYSUTCDATETIME()),
        CONSTRAINT [PK_Volatilities] PRIMARY KEY CLUSTERED ([SystemDate], [ProductSpec], [InstrumentType], [StartTradeMonth], [EndTradeMonth], [PutCallFlag], [StrikeType], [StrikePrice])
    );
END
GO

